import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { type Scenario, pooled, roundRobin, validateScenario } from "../src/index.js";

// Generated by the independent Python implementation: python -m reference.cross_check
const fixture = JSON.parse(readFileSync(new URL("./fixtures/cross-check.json", import.meta.url), "utf8")) as {
  cases: { scenario: Scenario; step: number; expected: { roundRobin: Record<string, number>; pooled: Record<string, number> } }[];
};

describe("agrees with the Python reference implementation", () => {
  fixture.cases.forEach(({ scenario, step, expected }, i) => {
    it(`case ${i}`, () => {
      validateScenario(scenario);
      const tol = 1e-6 * Math.max(1, ...scenario.funders.map((f) => f.budget));
      const rr = roundRobin(scenario, { step }).grants;
      const pl = pooled(scenario).grants;
      for (const a of scenario.applications) {
        expect(Math.abs(rr[a.id]! - expected.roundRobin[a.id]!)).toBeLessThanOrEqual(tol);
        expect(Math.abs(pl[a.id]! - expected.pooled[a.id]!)).toBeLessThanOrEqual(tol);
      }
    });
  });
});
